import pytest
from playwright.sync_api import expect
from sites.saucedemo.pages.login_page import LoginPage
from sites.saucedemo.pages.inventory_page import InventoryPage
from sites.saucedemo.pages.cart_page import CartPage
from sites.saucedemo.config import Config


class TestCartRemoveItems:

    @pytest.fixture(autouse=True)
    def login(self, page):
        login_page = LoginPage(page)
        login_page.navigate()
        login_page.login(Config.STANDARD_USER, Config.PASSWORD)

    def test_remove_single_item_leaves_cart_empty(self, page):
        """AC-1: With one item ("Sauce Labs Backpack") in the cart, removing it on the cart page leaves the cart with 0 items."""
        inventory_page = InventoryPage(page)
        inventory_page.add_item_to_cart("Sauce Labs Backpack")
        inventory_page.go_to_cart()

        cart_page = CartPage(page)
        assert cart_page.get_cart_item_count() == 1

        cart_page.remove_item("Sauce Labs Backpack")

        assert cart_page.get_cart_item_count() == 0

    def test_remove_one_of_two_items_leaves_the_other(self, page):
        """AC-2: With two items ("Sauce Labs Backpack" and "Sauce Labs Bike Light") in the cart, removing the backpack on the cart page leaves only "Sauce Labs Bike Light"."""
        inventory_page = InventoryPage(page)
        inventory_page.add_item_to_cart("Sauce Labs Backpack")
        inventory_page.add_item_to_cart("Sauce Labs Bike Light")
        inventory_page.go_to_cart()

        cart_page = CartPage(page)
        assert cart_page.get_cart_item_count() == 2

        cart_page.remove_item("Sauce Labs Backpack")

        assert cart_page.get_cart_item_count() == 1
        item_names = cart_page.get_item_names()
        assert item_names == ["Sauce Labs Bike Light"]

    def test_cart_badge_disappears_after_removing_only_item(self, page):
        """AC-3: After the only item in the cart is removed, the cart badge is no longer shown."""
        inventory_page = InventoryPage(page)
        inventory_page.add_item_to_cart("Sauce Labs Backpack")
        inventory_page.go_to_cart()

        cart_page = CartPage(page)
        assert cart_page.get_cart_item_count() == 1

        cart_page.remove_item("Sauce Labs Backpack")

        expect(inventory_page.cart_badge).to_have_count(0)
